use hkia_save_core::{session::*,writer::{Edit,Proof},archive::{ZipIndex,SLOT},native::ModelState,read_slot};
const A:&[u8]=include_bytes!("fixtures/writer-3.0.0-good.zip");
const B:&[u8]=include_bytes!("fixtures/writer-3.0.1-good.zip");
fn history()->Edit{Edit::History{item:2,old:638000000000000001,next:638000000010000001}}
fn progress()->Edit{Edit::FwishesProgress{achievement:4,counter:20,old_bits:7f32.to_bits(),next_bits:0f32.to_bits()}}
fn open(s:&mut ProductSession,id:u64,z:&[u8])->Reply{let expected=s.stamp();s.dispatch(Request{id,expected,command:Command::Open{kind:InputKind::Zip,bytes:z.to_vec()}})}
fn start(z:&[u8])->ProductSession{let mut s=ProductSession::new_private_writer([7;16]).unwrap();assert!(open(&mut s,1,z).result.is_ok());s}
fn w(s:&mut ProductSession,id:u64,command:WriterCommand)->WriterReply{let expected=s.stamp();s.dispatch_writer(WriterRequest{id,expected,command})}
fn ok(s:&mut ProductSession,id:u64,cmd:WriterCommand)->WriterPayload{let r=w(s,id,cmd);assert!(r.output.is_none());r.result.unwrap()}
fn reject(s:&mut ProductSession,id:u64,cmd:WriterCommand){let stamp=s.stamp();let r=w(s,id,cmd);assert!(r.result.is_err());assert!(r.output.is_none());assert_eq!(r.stamp,stamp)}
fn plan(s:&mut ProductSession,id:u64,edits:Vec<Edit>){assert!(matches!(ok(s,id,WriterCommand::Plan{edits}),WriterPayload::Plan(_)))}
fn apply(s:&mut ProductSession,id:u64,plan:u64)->Proof{match ok(s,id,WriterCommand::Apply{plan}){WriterPayload::Applied(p)=>p,_=>panic!()}}
fn export(s:&mut ProductSession,id:u64)->Vec<u8>{ok(s,id,WriterCommand::Verify);let r=w(s,id+1,WriterCommand::Export);assert!(matches!(r.result,Ok(WriterPayload::Exported{..})));r.output.unwrap()}
fn compare(z:&[u8],out:&[u8],h:bool,p:bool){let a=ZipIndex::parse(z).unwrap();let b=ZipIndex::parse(out).unwrap();assert_eq!(a.entries.len(),b.entries.len());for(x,y)in a.entries.iter().zip(&b.entries){assert_eq!(x.name,y.name);if x.name!=SLOT{assert_eq!(&z[x.local.clone()],&out[y.local.clone()]);}}let (sa,aa)=a.targets(z).unwrap();let (sb,ab)=b.targets(out).unwrap();assert_eq!(aa,ab);let a=read_slot(&sa.unwrap()).unwrap();let b=read_slot(&sb.unwrap()).unwrap();assert_eq!(a.index.documents,b.index.documents);assert_eq!(b.index.collections.iter().find(|x|x.id==2).unwrap().ticks,if h{638000000010000001}else{638000000000000001});let v=if p{0.0}else{7.0};assert!(matches!(b.index.achievements.iter().find(|x|x.id==4).unwrap().state,ModelState::Achievement{current,complete:false,completed:None}if current==v));assert!(matches!(b.index.counters.iter().find(|x|x.id==20).unwrap().state,ModelState::Counter{current,..}if current==v));}
fn round(z:&[u8],edits:Vec<Edit>,fields:u32,h:bool,p:bool){let mut s=start(z);let st=s.stamp();plan(&mut s,2,edits);let q=ok(&mut s,3,WriterCommand::Preview{plan:2});assert_eq!(s.stamp(),st);reject(&mut s,4,WriterCommand::Export);let proof=apply(&mut s,5,2);assert!(matches!(q,WriterPayload::Preview{proof:p,..}if p==proof));assert_eq!(proof.fields,fields);assert_eq!(proof.non_target_frames,3);assert!(proof.reused_blocks>0&&proof.reencoded_blocks>0);assert_eq!(s.stamp().revision,1);assert_eq!(s.stamp().source,st.source);reject(&mut s,6,WriterCommand::Export);let out=export(&mut s,7);assert_ne!(out,z);compare(z,&out,h,p);reject(&mut s,9,WriterCommand::Export);assert_eq!(w(&mut s,10,WriterCommand::Backup).output.unwrap(),z);}
#[test]fn history_300(){round(A,vec![history()],1,true,false)}
#[test]fn history_301(){round(B,vec![history()],1,true,false)}
#[test]fn progress_300(){round(A,vec![progress()],2,false,true)}
#[test]fn progress_301(){round(B,vec![progress()],2,false,true)}
#[test]fn batch_300(){round(A,vec![history(),progress()],3,true,true)}
#[test]fn batch_301(){round(B,vec![history(),progress()],3,true,true)}
#[test]fn length_change(){for z in [A,B]{let mut s=start(z);plan(&mut s,2,vec![Edit::History{item:3,old:9,next:638000000010000001}]);apply(&mut s,3,2);let out=export(&mut s,4);let a=ZipIndex::parse(&out).unwrap();let slot=read_slot(&a.targets(&out).unwrap().0.unwrap()).unwrap();assert_eq!(slot.index.collections.iter().find(|x|x.id==3).unwrap().ticks,638000000010000001);}}
#[test]fn undo_redo_reset(){let mut s=start(A);plan(&mut s,2,vec![history()]);apply(&mut s,3,2);let out=export(&mut s,4);ok(&mut s,6,WriterCommand::Undo);assert_eq!(s.stamp().revision,2);reject(&mut s,7,WriterCommand::Verify);ok(&mut s,8,WriterCommand::Redo);assert_eq!(export(&mut s,9),out);ok(&mut s,11,WriterCommand::Reset);assert_eq!(w(&mut s,12,WriterCommand::Backup).output.unwrap(),A);reject(&mut s,13,WriterCommand::Verify);ok(&mut s,14,WriterCommand::Undo);assert_eq!(export(&mut s,15),out);}
#[test]fn wrong_values_and_duplicates(){let mut s=start(A);for(i,e)in [vec![],vec![Edit::History{item:999,old:9,next:10}],vec![Edit::History{item:2,old:9,next:10}],vec![Edit::History{item:3,old:9,next:0}],vec![history(),history()],vec![progress(),progress()],vec![Edit::FwishesProgress{achievement:3,counter:20,old_bits:7f32.to_bits(),next_bits:0}],vec![Edit::FwishesProgress{achievement:4,counter:20,old_bits:8f32.to_bits(),next_bits:0}],vec![Edit::FwishesProgress{achievement:4,counter:20,old_bits:7f32.to_bits(),next_bits:8f32.to_bits()}],vec![Edit::FwishesProgress{achievement:4,counter:20,old_bits:7f32.to_bits(),next_bits:100f32.to_bits()}],vec![Edit::FwishesProgress{achievement:4,counter:20,old_bits:7f32.to_bits(),next_bits:f32::NAN.to_bits()}]].into_iter().enumerate(){reject(&mut s,2+i as u64,WriterCommand::Plan{edits:e})}}
#[test]fn guard_rejects(){for z in [include_bytes!("fixtures/writer-3.0.0-group.zip").as_slice(),include_bytes!("fixtures/writer-3.0.0-counter.zip"),include_bytes!("fixtures/writer-3.0.0-counted.zip"),include_bytes!("fixtures/writer-3.0.0-root.zip"),include_bytes!("fixtures/writer-3.0.0-rootcount.zip"),include_bytes!("fixtures/writer-3.0.0-migration.zip"),include_bytes!("fixtures/writer-3.0.1-group.zip"),include_bytes!("fixtures/writer-3.0.1-counter.zip"),include_bytes!("fixtures/writer-3.0.1-counted.zip"),include_bytes!("fixtures/writer-3.0.1-root.zip"),include_bytes!("fixtures/writer-3.0.1-rootcount.zip"),include_bytes!("fixtures/writer-3.0.1-migration.zip")]{let mut s=start(z);reject(&mut s,2,WriterCommand::Plan{edits:vec![history(),progress()]});assert_eq!(w(&mut s,3,WriterCommand::Backup).output.unwrap(),z);}}
#[test]fn stale_replay_foreign(){let mut s=start(A);let st=s.stamp();plan(&mut s,2,vec![history()]);apply(&mut s,3,2);reject(&mut s,3,WriterCommand::Verify);let r=s.dispatch_writer(WriterRequest{id:4,expected:st,command:WriterCommand::Verify});assert_eq!(r.result,Err(SessionError::Stale));let mut st=s.stamp();st.runtime=[8;16];let r=s.dispatch_writer(WriterRequest{id:5,expected:st,command:WriterCommand::Verify});assert_eq!(r.result,Err(SessionError::Foreign));reject(&mut s,6,WriterCommand::Apply{plan:2});}
#[test]fn file_switch_and_failed_open(){let mut s=start(A);plan(&mut s,2,vec![history()]);let st=s.stamp();assert!(open(&mut s,3,b"bad").result.is_err());assert_eq!(s.stamp(),st);assert!(open(&mut s,4,B).result.is_ok());reject(&mut s,5,WriterCommand::Apply{plan:2});assert_eq!(w(&mut s,6,WriterCommand::Backup).output.unwrap(),B);let expected=s.stamp();assert!(s.dispatch(Request{id:7,expected,command:Command::Close}).result.is_ok());reject(&mut s,8,WriterCommand::Backup);}
#[test]fn default_readonly(){let mut s=ProductSession::new([7;16]).unwrap();assert!(open(&mut s,1,A).result.is_ok());reject(&mut s,2,WriterCommand::Plan{edits:vec![history()]});let expected=s.stamp();assert_eq!(s.dispatch(Request{id:3,expected,command:Command::Apply}).result,Err(SessionError::Unsupported));}
#[test]fn replacement_plan_and_atomic(){let mut s=start(A);plan(&mut s,2,vec![history()]);plan(&mut s,3,vec![progress()]);reject(&mut s,4,WriterCommand::Apply{plan:2});apply(&mut s,5,3);let out=export(&mut s,6);compare(A,&out,false,true);reject(&mut s,8,WriterCommand::Plan{edits:vec![history(),progress()]});assert_eq!(export(&mut s,9),out);}
